        '점화 피해 +35%, 점화가 점화 확률의 40% 확률로 30% 증폭되고, 증폭된 점화 위에 새 점화가 걸리면 남은 점화 피해의 15%가 바로 터짐': '発火ダメージ +35%、発火が発火確率の40%の確率で30%増幅され、増幅した発火の上に新しい発火が掛かると残った発火ダメージの15%がすぐ弾ける',
        '포션 스킬 피해 +60%, 화염 피해 +35%, 처치한 적이 15% 확률로 터져 다른 적에게 그 적 최대 생명력 20%의 피해': 'ポーションスキルダメージ +60%、火ダメージ +35%、倒した敵が15%の確率で弾け、他の敵にその敵の最大生命力20%のダメージ',
        '물리 피해 감소 +6%, 회피 +15%, 점화에 걸리지 않음': '物理ダメージ軽減 +6%、回避 +15%、発火にかからない',
        '포션 스킬 피해 +120%, 범위 피해 +50%, 타격 시 10% 확률로 준 피해의 60%를 다른 적 모두에게': 'ポーションスキルダメージ +120%、範囲ダメージ +50%、打撃時に10%の確率で与えたダメージの60%を他のすべての敵に',
        '물리 피해 10% 증폭, 방어도 15% 증가': '物理ダメージ 10%増幅、防御力 15%増加',
        '치명타 및 연속 공격 발생 시 각각 2초간 공격속도 +3% (각각 최대 5중첩)': 'クリティカルと連続攻撃の発生時、それぞれ2秒間攻撃速度 +3% (それぞれ最大5スタック)',
        '완갑 슬롯에 보조 무기 장착 가능': 'バックラースロットに補助武器を装着できる',
        '물리 피해 감소 무시가 마이너스까지 적용될 수 있음': '物理ダメージ軽減無視がマイナスまで適用されうる',
        '피격 시 5초간 물리 피해 +6% (최대 5중첩, 곱연산)': '被弾時5秒間物理ダメージ +6% (最大5スタック、乗算)',
        '쌍수 상태에서, 각 무기의 효과 50% 증가': '二刀流状態で、各武器の効果 50%増加',
        '생명력 50% 이하 시 받는 피해 15% 감폭, 주는 피해 10% 증폭': '生命力50%以下で受けるダメージ 15%減幅、与えるダメージ 10%増幅',
        '생명력이 50% 이상으로 회복/흡수되지 않음, 치명타 확률 +3%p, 치명타 피해 배율 +15%, 연속 타격 +5%, 공격 속도 5% 증폭, 이동 속도 15% 증폭, 최종 피해 3% 증폭': '生命力が50%以上に回復/吸収されない、クリティカル率 +3%p、クリティカルダメージ倍率 +15%、連続打撃 +5%、攻撃速度 5%増幅、移動速度 15%増幅、最終ダメージ 3%増幅',
        '모든 주는 피해 10% 증폭, 받는 피해 10% 증폭': 'すべての与えるダメージ 10%増幅、受けるダメージ 10%増幅',
        '물리 피해 15% 증폭, 물리가 아닌 피해 20% 감폭': '物理ダメージ 15%増幅、物理以外のダメージ 20%減幅',
        '연속 타격 발생 시 3초간 공격 속도 +2%, 회피 +3% (최대 12중첩)': '連続打撃の発生時3秒間攻撃速度 +2%、回避 +3% (最大12スタック)',
        '치명타가 아닌 타격 시 다음 타격 치명타 확률 +5%p, 치명타 발동 시 초기화': 'クリティカルでない打撃時、次の打撃のクリティカル率 +5%p、クリティカル発動時にリセット',
        '적이 3기 이상 주변에 있으면 받는 피해 20% 감폭, 주는 피해 20% 증폭': '敵が3体以上周囲にいると受けるダメージ 20%減幅、与えるダメージ 20%増幅',
        '이동 후 첫 타격 피해 30% 증폭 및 첫 받는 피해 30% 감폭': '移動後の最初の打撃ダメージ 30%増幅、最初に受けるダメージ 30%減幅',
        '공격 후 적 생명력 20% 미만 즉시 처치(보스 10%)': '攻撃後、敵の生命力20%未満なら即時討伐(ボスは10%)',
        '회피 150당 연속 타격 +1%p(최대 +15%p), 방어도 500당 치명타 확률 +1%p(최대 +10%p)': '回避150につき連続打撃 +1%p (最大 +15%p)、防御力500につきクリティカル率 +1%p (最大 +10%p)',
