        '막기 확률 및 비껴내기 확률 판정에 행운 적용(2회 굴려 유리한 값 선택)': 'ブロック率と受け流し率の判定に幸運を適用(2回振って有利な値を選ぶ)',
        '치명타 피해 배율 +66%, 치명타 확률 -6%p': 'クリティカルダメージ倍率 +66%、クリティカル率 -6%p',
        '이동 시 흐릿함 상태 부여: 이동 속도 +20%, 치명타 피해 배율 +25%, 회피 20% 증폭. 피해를 받으면 해제': '移動時にぼやけ状態を付与: 移動速度 +20%、クリティカルダメージ倍率 +25%、回避 20%増幅。ダメージを受けると解除',
        '치명타 발생 시 5초간 대상 받는 피해 +2% (개별 대상, 최대 10중첩, 적 상태이상에 표시)': 'クリティカル発生時5秒間対象の受けるダメージ +2% (対象ごと、最大10スタック、敵の状態異常に表示)',
        '물리 피해 감소 무시 +25%, 저항 관통 +25%, 피해 8% 감폭': '物理ダメージ軽減無視 +25%、耐性貫通 +25%、ダメージ 8%減幅',
        '모든 공격이 치명타로 간주됩니다. 치명타로 간주된 비-치명타 공격도 치명타 효과와 치명타 피해 배율 보너스를 받습니다.': 'すべての攻撃がクリティカルとみなされます。クリティカルとみなされた非クリティカル攻撃もクリティカル効果とクリティカルダメージ倍率ボーナスを受けます。',
        '현재 생명력 66% 초과 시 치명타 피해 배율 20% 증폭, 이하 시 회피 20% 증폭': '現在生命力66%超でクリティカルダメージ倍率 20%増幅、以下で回避 20%増幅',
        '적이 1명일 경우 치명타가 원 피해의 50%로 한 번 더 들어감, 치명타 피해 배율 -200%': '敵が1体の場合クリティカルが元のダメージの50%でもう一度入る、クリティカルダメージ倍率 -200%',
        '치명타 피해 배율이 1.5배, 피해 25% 감폭': 'クリティカルダメージ倍率が1.5倍、ダメージ 25%減幅',
        '치명타 피해 배율 20% 증폭 및 회피 20% 증폭': 'クリティカルダメージ倍率 20%増幅と回避 20%増幅',
        '이동 속도 15% 증폭, 방어도/에너지 보호막 0': '移動速度 15%増幅、防御力/エネルギーシールド 0',
        '공격 속도 15% 증폭': '攻撃速度 15%増幅',
        '투사체 스킬 타겟 수 +2, 투사체 스킬 최소 피해 보정 -10%': '投射物スキルの対象数 +2、投射物スキルの最小ダメージ補正 -10%',
        '이동 속도 1%당 공격 속도 0.1% 증폭': '移動速度1%につき攻撃速度 0.1%増幅',
