        '투사체 스킬 타겟 수 +1, 타겟마다 피해 4% 증폭': '投射物スキルの対象数 +1、対象ごとにダメージ 4%増幅',
        '피격되지 않은 시간 1초마다 치명타 확률 +3%p (피격 시 초기화)': '被弾していない時間1秒ごとにクリティカル率 +3%p (被弾時にリセット)',
        '공격 속도와 이동 속도 상호 12% 효율 보정, 최대 생명력 -15%': '攻撃速度と移動速度が相互に12%の効率で補正、最大生命力 -15%',
        '공격 속도 소프트캡 기준치 +2': '攻撃速度ソフトキャップの基準値 +2',
        '원소 최종 피해 15% 증폭, 물리 피해 없음': '元素最終ダメージ 15%増幅、物理ダメージなし',
        '모든 원소 저항 +15%, 원소 저항 최대치 +3%, 카오스 저항 -10%': 'すべての元素耐性 +15%、元素耐性の最大値 +3%、カオス耐性 -10%',
        '에너지 보호막 재생이 끊기지 않음, 최대 생명력 -15%': 'エネルギーシールド再生が途切れない、最大生命力 -15%',
        '모든 스킬이 화염/냉기/번개 33% 영향 스킬로 변화': 'すべてのスキルが火/冷気/雷33%影響スキルに変化',
        '카오스 저항이 가장 높은 원소 저항의 50%만큼 상승, 카오스 저항만큼 원소 최종 피해 증가': 'カオス耐性が最も高い元素耐性の50%分上昇、カオス耐性分元素最終ダメージ増加',
        '저항 관통 +20%, 치명타 피해 배율 -25%': '耐性貫通 +20%、クリティカルダメージ倍率 -25%',
        '화/냉/번 동시 사용 시 최종 피해 5% 증폭, 상태이상 강도는 최종 피해의 1.5배에 비례': '火/冷気/雷の同時使用で最終ダメージ 5%増幅、状態異常の強度は最終ダメージの1.5倍に比例',
