        '원소 저항 관통 +30%, 원소 저항 관통이 -300%까지 확장됨': '元素耐性貫通 +30%、元素耐性貫通が-300%まで拡張される',
        '모든 피해가 카오스 피해가 됨. 카오스 피해 10% 증폭': 'すべてのダメージがカオスダメージになる。カオスダメージ 10%増幅',
