        '에너지 보호막 재생 불가, 흡수가 에너지 보호막에 대신 적용': 'エネルギーシールド再生不可、吸収がエネルギーシールドに代わりに適用',
        '각 원소 저항 최대치 초과분의 25%만큼 카오스 저항 증가': '各元素耐性の最大値超過分の25%分カオス耐性増加',
        'DOT 틱 속도 +50%, 지속시간 -50%': 'DOTのティック速度 +50%、持続時間 -50%',
