        '에너지 보호막 50% 이상에서 피해 10% 증폭. 공격 시 가능하면 생명력 4%를 소모해 해당 공격의 피해 10% 증폭': 'エネルギーシールド50%以上でダメージ 10%増幅。攻撃時に可能なら生命力4%を消費してその攻撃のダメージ 10%増幅',
        '주얼 슬롯 2칸 추가, 카오스 피해 15% 증폭, 생명력 회복 효과 50% 감폭': 'ジュエルスロット2欄追加、カオスダメージ 15%増幅、生命力回復効果 50%減幅',
        '저주 최대치 +1. 카오스 피해로 적 처치 시 50% 확률로 시체 폭발(적 최대 생명력의 20%를 카오스 피해로 주변에). 모든 카오스 피해 적중 시 적에게 위축 부여(최대 10중첩, 1중첩당 받는 카오스 피해 +2%)': '呪いの最大数 +1。カオスダメージで敵を倒すと50%の確率で死体爆発(敵の最大生命力の20%をカオスダメージとして周囲に)。すべてのカオスダメージ命中時に敵へ萎縮を付与(最大10スタック、1スタックにつき受けるカオスダメージ +2%)',
        '소환수 기본 피해 15% 증폭': '召喚獣の基本ダメージ 15%増幅',
